        for i in range(N):
            v = X[i]
            if v in AllIndices:
                AllIndices[v].append(i)
            else:
                AllIndices[v] = [i]

        delta = [0] * (N + 2)

        for u in range(N):
            t = time_val[u]
            Lu = L[u]
            Ru = R[u]
