                for i in range(Lu, u + 1):
                    target = X[i] + K
                    lst = AllIndices.get(target)
                    if lst is not None:
                        low = u if u > i + 1 else i + 1
                        high = Ru if Ru < i + K else i + K
                        if low <= high:
                            if len(lst) == 1:
                                if low <= lst[0] <= high:
                                    delta[t] += 1
                            elif lst[0] <= high and lst[-1] >= low:
                                delta[t] += b_right(lst, high) - b_left(lst, low)
            else:
                for j in range(u, Ru + 1):
                    target = X[j] - K
                    lst = AllIndices.get(target)
                    if lst is not None:
                        low = Lu if Lu > j - K else j - K
                        high = u if u < j - 1 else j - 1
                        if low <= high:
                            if len(lst) == 1:
                                if low <= lst[0] <= high:
                                    delta[t] += 1
                            elif lst[0] <= high and lst[-1] >= low:
                                delta[t] += b_right(lst, high) - b_left(lst, low)
        return delta

    P = [i + A[i] for i in range(N)]
    M = [i - A[i] for i in range(N)]

    delta_P = solve_X(P)
    delta_M = solve_X(M)

    delta_part3 = [0] * (N + 2)
    if K < N:
        window_size = K + 1
        deq = deque()
