                deq.pop()
            deq.append(i)
            if deq[0] <= i - window_size:
                deq.popleft()
            if i >= K:
                if A[i - K] == A[i]:
                    t = time_val[deq[0]]
                    delta_part3[t] += 1

    total = 0
    for t in range(1, N + 1):
        total += delta_P[t] + delta_M[t] - delta_part3[t]

    ans = [0] * (Q + 1)
    ans[0] = total
    for t in range(1, Q + 1):
        d = delta_P[t] + delta_M[t] - delta_part3[t]
        total -= d
        ans[t] = total

    sys.stdout.write('\n'.join(map(str, ans)) + '\n')

